```javascript
// Improved application with security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { validator, validate } = require('express-json-validator-middleware');

const app = express();

// 1. SECURITY HEADERS
app.use(helmet());

// 2. REQUEST SIZE LIMIT (prevent DoS)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// 3. RATE LIMITING (prevent brute-force/DoS)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api', limiter);

// 4. INPUT VALIDATION SCHEMAS
const userQuerySchema = {
  type: 'object',
  properties: {
    limit: { type: 'integer', minimum: 1, maximum: 100 },
    offset: { type: 'integer', minimum: 0 },
  },
};

// 5. HEALTH ENDPOINT
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// 6. USERS ENDPOINT WITH INPUT VALIDATION
// Using the validator middleware
app.get('/users', validate({ query: userQuerySchema }), (req, res) => {
  const { limit = 10, offset = 0 } = req.query;

  // Additional manual validation as defense-in-depth
  const safeLimit = Math.min(Math.max(parseInt(limit, 10) || 10, 1), 100);
  const safeOffset = Math.max(parseInt(offset, 10) || 0, 0);

  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  res.json(users.slice(safeOffset, safeOffset + safeLimit));
});

// 7. GLOBAL ERROR HANDLER (must be last middleware)
app.use((err, req, res, next) => {
  // Log error details server-side only (don't expose internals)
  console.error(`[ERROR] ${err.message}`, {
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString(),
  });

  // Handle specific error types
  if (err.name === 'JsonSchemaValidation') {
    return res.status(400).json({ 
      error: 'Invalid request parameters',
      details: err.validationErrors 
    });
  }

  // Generic error response (don't leak stack traces in production)
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(statusCode).json({ error: message });
});

// 8. 404 HANDLER
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// 9. SECURE SERVER CONFIGURATION
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;
```

---

### Key Security Improvements Explained

| Improvement | Purpose |
|-------------|---------|
| **helmet** | Sets HTTP security headers (XSS protection, HSTS, etc.) |
| **Request size limits** | Prevents large payload DoS attacks |
| **Rate limiting** | Prevents brute-force and API abuse |
| **Input validation** | Validates query params against schemas |
| **Global error handler** | Prevents stack trace leakage, provides consistent errors |
| **404 handler** | Prevents information disclosure from unknown routes |
| **Graceful shutdown** | Prevents orphaned connections |

