const rateLimit = require('express-rate-limit');

// Initialize Express app
const app = express();

// Security: Set HTTP security headers
app.use(helmet());

// Security: Limit request size to prevent large payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Security: Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// Input validation helper
const validatePositiveInteger = (value, paramName) => {
  const parsed = parseInt(value, 10);
  if (isNaN(parsed) || parsed <= 0 || String(value) !== String(parsed)) {
    throw new Error(`Invalid ${paramName}: must be a positive integer`);
  }
  return parsed;
};

// Sanitize output to prevent XSS
const sanitizeUser = (user) => ({
  id: user.id,
  name: String(user.name).replace(/[<>]/g, ''),
  email: String(user.email).replace(/[<>]/g, ''),
});

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
  // Sanitize output to prevent XSS
  res.json(users.map(sanitizeUser));
});

// Example: User endpoint with input validation
app.get('/users/:id', (req, res, next) => {
  try {
    // Input validation
    const userId = validatePositiveInteger(req.params.id, 'user ID');

    // Mock user lookup ( replace with actual DB query with parameterized queries )
